-- Adds authentic Mapo Tofu (omnivorescookbook.com/authentic-mapo-tofu/) and
-- traditional Kimchi (mykoreankitchen.com/kimchi-recipe/) with EN/DE/ZH
-- translations. No image rows: the public renderer falls back to
-- images/recipe-placeholder.png when recipe_images is empty.
-- Wrangler applies each migration file inside a single D1 transaction, so all
-- writes below land atomically. INSERT OR IGNORE keeps the file idempotent.

INSERT OR IGNORE INTO recipes (id, slug, status, servings, prep_minutes, cook_minutes, total_minutes, difficulty, published_at) VALUES
  ('homepage-mapo-tofu', 'mapo-tofu', 'published', 4, 10, 20, 30, 'medium', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('homepage-kimchi', 'kimchi', 'published', 8, 60, 5, 65, 'medium', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));

INSERT OR IGNORE INTO recipe_translations (recipe_id, locale, title, description, origin, occasion, notes, ingredients_json, steps_json, nutrition_json) VALUES
  ('homepage-mapo-tofu', 'en', 'Authentic Mapo Tofu', 'Sichuan classic: silken tofu in a numbing chili-bean sauce with crispy pork and a hit of fresh-ground Sichuan peppercorn.', 'Sichuan', 'Weeknight', 'Adapted from omnivorescookbook.com', '[{"name":"500g soft tofu","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"200g ground pork or beef","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"3 tbsp peanut oil","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"1 tsp Sichuan peppercorns","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"2 tbsp doubanjiang (broad-bean chili paste)","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1 tbsp douchi (fermented black beans), rinsed","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"1 tbsp Sichuan chili powder","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"15g ginger, minced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"4 garlic cloves, minced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"240ml chicken or vegetable stock","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 tbsp light soy sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1 tsp sugar","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1/2 tsp ground white pepper","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"2 spring onions, sliced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 tbsp cornstarch + 2 tbsp water (slurry)","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true}]', '[{"text":"Toast Sichuan peppercorns in a dry pan over medium-low heat until fragrant, about 2 minutes. Cool and grind to a powder.","timerSeconds":120},{"text":"Cube tofu into 2 cm pieces. Soak in hot water with 1 tsp salt for 5 minutes, then drain gently.","timerSeconds":300},{"text":"Heat peanut oil in a wok over medium-high. Add the ground meat and stir-fry until crispy and deep brown, 3 to 4 minutes. Push to one side.","timerSeconds":240},{"text":"Lower the heat. Add doubanjiang and douchi to the oil and stir 30 seconds until the oil turns red and fragrant.","timerSeconds":30},{"text":"Add ginger, garlic and chili powder. Stir 30 seconds.","timerSeconds":30},{"text":"Pour in stock, soy sauce, sugar and white pepper. Slide in the tofu and swirl the pan to combine without breaking it. Simmer 4 minutes.","timerSeconds":240},{"text":"Stir the cornstarch slurry and add in three rounds, swirling between, until the sauce is glossy and coats the tofu.","timerSeconds":0},{"text":"Off the heat, dust with ground Sichuan peppercorns and the spring onions. Serve immediately over hot rice.","timerSeconds":0}]', '{}'),
  ('homepage-mapo-tofu', 'de', 'Authentisches Mapo Tofu', 'Sichuan-Klassiker: Seidentofu in scharfer Bohnenpaste mit knusprigem Hackfleisch und frisch gemahlenem Sichuan-Pfeffer.', 'Sichuan', 'Wochentag', 'Nach omnivorescookbook.com', '[{"name":"500g Seidentofu","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"200g Hackfleisch (Schwein oder Rind)","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"3 EL Erdnussöl","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"1 TL Sichuan-Pfeffer","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"2 EL Doubanjiang (scharfe Bohnenpaste)","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1 EL Douchi (fermentierte schwarze Bohnen), abgespült","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"1 EL Sichuan-Chilipulver","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"15g Ingwer, fein gehackt","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"4 Knoblauchzehen, fein gehackt","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"240ml Hühner- oder Gemüsebrühe","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 EL helle Sojasauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1 TL Zucker","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1/2 TL weißer Pfeffer, gemahlen","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"2 Frühlingszwiebeln, in Ringe geschnitten","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1 EL Speisestärke + 2 EL Wasser","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true}]', '[{"text":"Sichuan-Pfeffer in einer trockenen Pfanne bei mittlerer Hitze rösten, bis er duftet, etwa 2 Minuten. Abkühlen lassen und zu Pulver mahlen.","timerSeconds":120},{"text":"Tofu in 2 cm große Würfel schneiden. 5 Minuten in heißem Wasser mit 1 TL Salz ziehen lassen, dann vorsichtig abtropfen.","timerSeconds":300},{"text":"Erdnussöl im Wok auf mittlerer bis hoher Hitze erhitzen. Hackfleisch dazugeben und 3 bis 4 Minuten knusprig und dunkelbraun braten. Zur Seite schieben.","timerSeconds":240},{"text":"Hitze reduzieren. Doubanjiang und Douchi ins Öl geben und 30 Sekunden rühren, bis das Öl rot und duftend ist.","timerSeconds":30},{"text":"Ingwer, Knoblauch und Chilipulver dazugeben. 30 Sekunden rühren.","timerSeconds":30},{"text":"Brühe, Sojasauce, Zucker und weißen Pfeffer einrühren. Tofu sanft einlegen und durch Schwenken vermengen, ohne ihn zu brechen. 4 Minuten köcheln lassen.","timerSeconds":240},{"text":"Stärke-Mischung verrühren und in drei Portionen unter Schwenken zugeben, bis die Sauce glänzt und am Tofu haftet.","timerSeconds":0},{"text":"Vom Herd nehmen. Mit gemahlenem Sichuan-Pfeffer und Frühlingszwiebeln bestreuen. Sofort über heißem Reis servieren.","timerSeconds":0}]', '{}'),
  ('homepage-mapo-tofu', 'zh', '正宗麻婆豆腐', '四川经典：嫩豆腐烩在麻辣豆瓣酱中，配上酥香肉末和现磨花椒。', '四川', '日常', '改编自 omnivorescookbook.com', '[{"name":"500克 嫩豆腐","amount":"","unit":"","note":"","aisle":"Fresh / fridge","inStore":true},{"name":"200克 猪肉末或牛肉末","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"3汤匙 花生油","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"1茶匙 花椒","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"2汤匙 豆瓣酱","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1汤匙 豆豉，冲洗","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"1汤匙 四川辣椒粉","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"15克 姜，切末","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"4瓣 大蒜，切末","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"240毫升 鸡汤或蔬菜汤","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1汤匙 生抽","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"1茶匙 糖","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1/2茶匙 白胡椒粉","amount":"","unit":"","note":"","aisle":"Spices","inStore":true},{"name":"2根 葱，切段","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"1汤匙 玉米淀粉 + 2汤匙 水","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true}]', '[{"text":"干锅中小火烘花椒约 2 分钟至香。冷却后磨成粉。","timerSeconds":120},{"text":"豆腐切 2 厘米块。放入热水中加 1 茶匙盐，浸泡 5 分钟，轻轻沥干。","timerSeconds":300},{"text":"锅中放花生油，中高火加热。下肉末炒至焦香深褐，3 至 4 分钟，推到一边。","timerSeconds":240},{"text":"转小火。加入豆瓣酱和豆豉，炒 30 秒至油变红出香。","timerSeconds":30},{"text":"加入姜、蒜和辣椒粉，炒 30 秒。","timerSeconds":30},{"text":"倒入高汤、生抽、糖和白胡椒粉。轻轻放入豆腐，晃动锅使其混合，不要弄碎。煮 4 分钟。","timerSeconds":240},{"text":"拌匀水淀粉，分三次加入，每次晃动锅，直到酱汁浓稠光亮，挂在豆腐上。","timerSeconds":0},{"text":"关火，撒上花椒粉和葱花。趁热配米饭。","timerSeconds":0}]', '{}'),
  ('homepage-kimchi', 'en', 'Traditional Kimchi', 'Classic Korean baechu kimchi: napa cabbage cured in salt then layered with gochugaru, garlic, ginger and a sweet rice porridge.', 'Korea', 'Make-ahead', 'Adapted from mykoreankitchen.com. Plus 24 to 48 hours fermenting at room temperature.', '[{"name":"2kg napa cabbage (about 1 large head)","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"200g coarse sea salt","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2L cold water (for brining)","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"500ml water (for the rice porridge)","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"35g sweet rice flour","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"50g sugar","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"150g Korean radish (mu), julienned","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"100g carrot, julienned","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"50g onion, finely grated","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"6 spring onions, cut into 4 cm pieces","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"14 garlic cloves (about 40g), minced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"15g ginger, minced","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"80ml fish sauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"30g salted shrimp (saeujeot), finely chopped","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"100g Korean red pepper flakes (gochugaru)","amount":"","unit":"","note":"","aisle":"Spices","inStore":true}]', '[{"text":"Cut the cabbage lengthwise into quarters. Slice a deep notch in each core so leaves separate without falling apart.","timerSeconds":0},{"text":"Dip each quarter in 2 L salted water, then sprinkle salt between every leaf. Stand 2 hours, turning every 30 minutes.","timerSeconds":7200},{"text":"Rinse the cabbage 3 times in cold water. Drain core-side down for 30 minutes.","timerSeconds":1800},{"text":"Whisk water and sweet rice flour in a small pot. Cook on medium, stirring, until bubbling, about 5 minutes. Stir in sugar and cook 1 minute more until glossy. Cool completely.","timerSeconds":300},{"text":"In a large bowl combine the cooled porridge, fish sauce, salted shrimp, gochugaru, garlic and ginger. Mix in the radish, carrot and spring onions.","timerSeconds":0},{"text":"Wearing gloves, rub the paste over and between every leaf of each cabbage quarter.","timerSeconds":0},{"text":"Pack tightly into an airtight jar. Press down to remove air pockets and leave 2 to 3 cm of headspace.","timerSeconds":0},{"text":"Leave at room temperature for 24 to 48 hours to start the fermentation, then refrigerate. Best after 1 to 2 weeks.","timerSeconds":0}]', '{}'),
  ('homepage-kimchi', 'de', 'Traditionelles Kimchi', 'Klassisches koreanisches Baechu-Kimchi: Chinakohl in Salz gepökelt und mit Gochugaru, Knoblauch, Ingwer und süßem Reisbrei eingelegt.', 'Korea', 'Vorzubereiten', 'Nach mykoreankitchen.com. Dazu 24 bis 48 Stunden Fermentation bei Raumtemperatur.', '[{"name":"2kg Chinakohl (ca. 1 großer Kopf)","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"200g grobes Meersalz","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2L kaltes Wasser (zum Pökeln)","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"500ml Wasser (für den Reisbrei)","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"35g Klebreismehl","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"50g Zucker","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"150g koreanischer Rettich (Mu), in Streifen","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"100g Karotte, in Streifen","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"50g Zwiebel, fein gerieben","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"6 Frühlingszwiebeln, in 4 cm Stücken","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"14 Knoblauchzehen (ca. 40g), fein gehackt","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"15g Ingwer, fein gehackt","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"80ml Fischsauce","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"30g Salzgarnelen (Saeujeot), fein gehackt","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"100g koreanische Chiliflocken (Gochugaru)","amount":"","unit":"","note":"","aisle":"Spices","inStore":true}]', '[{"text":"Chinakohl längs vierteln. Im Strunk jedes Viertels einen tiefen Schnitt setzen, damit sich die Blätter leicht lösen lassen.","timerSeconds":0},{"text":"Jedes Viertel in 2 L gesalzenes Wasser tauchen, dann zwischen jeder Blattlage Salz streuen. 2 Stunden ziehen lassen, alle 30 Minuten wenden.","timerSeconds":7200},{"text":"Kohl dreimal in kaltem Wasser spülen. Mit dem Strunk nach unten 30 Minuten abtropfen lassen.","timerSeconds":1800},{"text":"Wasser und Klebreismehl im Topf verquirlen. Bei mittlerer Hitze unter Rühren ca. 5 Minuten kochen, bis es blubbert. Zucker einrühren und 1 weitere Minute glänzend kochen. Komplett abkühlen lassen.","timerSeconds":300},{"text":"In einer großen Schüssel den abgekühlten Brei, Fischsauce, Salzgarnelen, Gochugaru, Knoblauch und Ingwer vermengen. Rettich, Karotte und Frühlingszwiebeln unterheben.","timerSeconds":0},{"text":"Mit Handschuhen die Paste auf und zwischen jedem Blatt jedes Kohlviertels einreiben.","timerSeconds":0},{"text":"Fest in ein luftdichtes Glasgefäß packen. Andrücken, damit Luft entweicht, und 2 bis 3 cm Luft oben lassen.","timerSeconds":0},{"text":"24 bis 48 Stunden bei Raumtemperatur anfermentieren, dann kühlen. Am besten nach 1 bis 2 Wochen.","timerSeconds":0}]', '{}'),
  ('homepage-kimchi', 'zh', '传统韩式泡菜', '经典韩式辣白菜泡菜：大白菜用盐腌过，然后裹上辣椒粉、大蒜、姜和糯米糊。', '韩国', '提前制作', '改编自 mykoreankitchen.com。需在室温下发酵 24 至 48 小时。', '[{"name":"2公斤 大白菜（约 1 颗大的）","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"200克 粗海盐","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"2升 冷水（用于腌制）","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"500毫升 水（用于米糊）","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"35克 糯米粉","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"50克 糖","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"150克 韩国白萝卜，切丝","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"100克 胡萝卜，切丝","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"50克 洋葱，磨碎","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"6根 葱，切 4 厘米段","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"14瓣 大蒜（约 40 克），切末","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"15克 姜，切末","amount":"","unit":"","note":"","aisle":"","inStore":false},{"name":"80毫升 鱼露","amount":"","unit":"","note":"","aisle":"Sauces","inStore":true},{"name":"30克 韩式虾酱（saeujeot），切碎","amount":"","unit":"","note":"","aisle":"Pantry","inStore":true},{"name":"100克 韩国辣椒粉（gochugaru）","amount":"","unit":"","note":"","aisle":"Spices","inStore":true}]', '[{"text":"大白菜纵向切成四瓣。在每瓣的菜心处划一刀深口，让叶片便于分开。","timerSeconds":0},{"text":"将每瓣白菜浸入 2 升盐水，然后在每层叶片之间撒盐。静置 2 小时，每 30 分钟翻一次。","timerSeconds":7200},{"text":"用冷水冲洗白菜 3 次。菜心向下沥干 30 分钟。","timerSeconds":1800},{"text":"小锅中将水和糯米粉打匀。中火持续搅拌，约 5 分钟至沸腾起泡。加糖再煮 1 分钟至发亮。完全冷却。","timerSeconds":300},{"text":"大碗中混合冷却的米糊、鱼露、虾酱、辣椒粉、大蒜和姜。加入萝卜丝、胡萝卜丝和葱段，拌匀。","timerSeconds":0},{"text":"戴手套，将酱料涂抹在每瓣白菜的每一层叶片上。","timerSeconds":0},{"text":"紧密装入密封玻璃罐，压实排气，顶部留 2 至 3 厘米空间。","timerSeconds":0},{"text":"室温发酵 24 至 48 小时启动发酵，然后冷藏。1 至 2 周后风味最佳。","timerSeconds":0}]', '{}');

INSERT OR IGNORE INTO recipe_tags (recipe_id, tag) VALUES
  ('homepage-mapo-tofu', 'spicy'),
  ('homepage-kimchi', 'spicy');
